@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Oswald:wght@500;600;700&display=swap');

:root {
  /* Brand Colors in OKLCH */
  --brand-primary: oklch(55% 0.22 25);    /* RedRoom Red (#E63946 equivalent) */
  --brand-primary-hover: oklch(45% 0.22 25);
  --bg-surface: oklch(14% 0 0);           /* Charcoal Black (#141414 equivalent) */
  --bg-elevated: oklch(22% 0 0);          /* Lighter surface */
  --bg-input: oklch(18% 0 0);

  --text-primary: oklch(98% 0 0);         /* White */
  --text-secondary: oklch(75% 0 0);       /* Light Gray */
  --text-error: oklch(65% 0.2 25);

  --border-color: oklch(30% 0 0);

  /* Typography */
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 6rem;
  --space-2xl: 10rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-full: 9999px;
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-family: var(--font-body);
  background-color: var(--bg-surface);
  color: var(--text-primary);
  line-height: 1.5;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

img, picture, video, canvas, svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

button, input, select {
  font: inherit;
  color: inherit;
}

ul {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  line-height: 1.1;
  font-weight: 700;
  letter-spacing: 0.02em;
}

h1 { font-size: clamp(3rem, 8vw, 6rem); }
h2 { font-size: clamp(2.5rem, 6vw, 4.5rem); }
h3 { font-size: clamp(1.75rem, 4vw, 3rem); }
h4 { font-size: clamp(1.25rem, 3vw, 2rem); }

p {
  color: var(--text-secondary);
  font-size: 1.125rem;
  max-width: 65ch;
  margin-bottom: var(--space-md);
}

p.lead {
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
}

/* Utility */
.container {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.text-center { text-align: center; }
.text-red { color: var(--brand-primary); }
.d-none { display: none !important; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1rem 2rem;
  background-color: var(--brand-primary);
  color: var(--text-primary);
  font-family: var(--font-heading);
  text-transform: uppercase;
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  border: 2px solid var(--brand-primary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: var(--brand-primary-hover);
  border-color: var(--brand-primary-hover);
}

.btn-outline {
  background-color: transparent;
  color: var(--brand-primary);
}

.btn-outline:hover {
  background-color: var(--brand-primary);
  color: var(--text-primary);
}

.btn-white {
  background-color: var(--text-primary);
  color: var(--bg-surface);
  border-color: var(--text-primary);
}

.btn-white:hover {
  background-color: var(--text-secondary);
  border-color: var(--text-secondary);
}

/* Navigation */
.top-bar {
  background-color: var(--brand-primary);
  color: var(--text-primary);
  padding: var(--space-xs);
  text-align: center;
  font-size: 0.875rem;
  font-weight: 600;
}

.top-bar a {
  text-decoration: underline;
  margin-left: var(--space-xs);
}

.navbar {
  padding: var(--space-md) 0;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  background-color: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(12px);
  z-index: 100;
}

.navbar .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.brand {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: var(--brand-primary);
  letter-spacing: 0.05em;
}

.nav-links {
  display: flex;
  gap: var(--space-md);
  align-items: center;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav-links a:hover {
  color: var(--brand-primary);
}

/* Mobile Nav Toggle */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.5rem;
  cursor: pointer;
}

/* Hero Section */
.hero {
  min-height: 80vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding: var(--space-xl) 0;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(135deg, rgba(20,20,20,0.9) 0%, rgba(20,20,20,0.4) 100%);
  z-index: 1;
}

.hero-bg {
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  object-fit: cover;
  z-index: 0;
  filter: grayscale(80%) contrast(1.2);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.hero-content h1 {
  margin-bottom: var(--space-md);
  text-shadow: 2px 4px 12px rgba(0,0,0,0.5);
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  margin-top: var(--space-lg);
}

/* Sections */
.section {
  padding: var(--space-xl) 0;
}

.section-darker {
  background-color: var(--bg-elevated);
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
  align-items: center;
}

/* Cards */
.card {
  background-color: var(--bg-elevated);
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  transition: transform 0.3s ease;
}

.card:hover {
  transform: translateY(-5px);
  border-color: var(--brand-primary);
}

.card h3 {
  margin-bottom: var(--space-sm);
}

/* Floor vs Treadmill Toggle */
.toggle-wrapper {
  display: flex;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.toggle-btn {
  padding: 1rem 3rem;
  background-color: var(--bg-elevated);
  border: 2px solid var(--border-color);
  color: var(--text-secondary);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  cursor: pointer;
  transition: all 0.3s ease;
}

.toggle-btn:first-child {
  border-radius: var(--radius-sm) 0 0 var(--radius-sm);
  border-right: none;
}

.toggle-btn:last-child {
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

.toggle-btn.active {
  background-color: var(--brand-primary);
  border-color: var(--brand-primary);
  color: var(--text-primary);
}

.toggle-content-pane {
  display: none;
  animation: fadeIn 0.4s ease;
}

.toggle-content-pane.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Instructor Grid & Filtering */
.filter-bar {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: var(--space-lg);
}

.filter-btn {
  padding: 0.5rem 1.5rem;
  border: 1px solid var(--border-color);
  background: var(--bg-elevated);
  color: var(--text-secondary);
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all 0.2s;
}

.filter-btn:hover, .filter-btn.active {
  background: var(--text-primary);
  color: var(--bg-surface);
  border-color: var(--text-primary);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-lg);
}

.instructor-card {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-md);
  aspect-ratio: 3/4;
  background-color: var(--bg-elevated);
}

.instructor-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
  filter: grayscale(100%);
}

.instructor-card:hover img {
  transform: scale(1.05);
  filter: grayscale(0%);
}

.instructor-info {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: var(--space-md);
  background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
}

.instructor-info h3 {
  margin-bottom: 0.25rem;
}

.instructor-info p {
  margin-bottom: var(--space-sm);
  font-size: 0.875rem;
  color: var(--brand-primary);
  font-weight: 600;
  text-transform: uppercase;
}

/* FAQ Accordion */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-header {
  width: 100%;
  text-align: left;
  padding: var(--space-md) 0;
  background: none;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.accordion-header::after {
  content: '+';
  font-size: 2rem;
  color: var(--brand-primary);
  transition: transform 0.3s;
}

.accordion-item.active .accordion-header::after {
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.accordion-item.active .accordion-content {
  max-height: 500px; /* arbitrary large value */
}

.accordion-content p {
  padding-bottom: var(--space-md);
}

/* Schedule Table */
.schedule-table-container {
  overflow-x: auto;
  margin-bottom: var(--space-xl);
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

.schedule-table th, .schedule-table td {
  padding: var(--space-md);
  border-bottom: 1px solid var(--border-color);
}

.schedule-table th {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  color: var(--text-primary);
  width: 30%;
}

.schedule-table td {
  font-size: 1.25rem;
  color: var(--brand-primary);
  font-weight: 600;
}

/* Lifestyle Carousel */
.carousel-container {
  position: relative;
  max-width: 100%;
  overflow: hidden;
  padding: var(--space-xl) 0;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1);
  will-change: transform;
}

.carousel-slide {
  min-width: 80%;
  padding: 0 var(--space-sm);
  opacity: 0.5;
  transition: opacity 0.5s;
  transform: scale(0.95);
  transition: transform 0.5s, opacity 0.5s;
}

.carousel-slide.active {
  opacity: 1;
  transform: scale(1);
}

.carousel-slide img {
  border-radius: var(--radius-md);
  aspect-ratio: 16/9;
  object-fit: cover;
  width: 100%;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 60px;
  height: 60px;
  background: rgba(0,0,0,0.7);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 50%;
  font-size: 2rem;
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-btn:hover {
  background: var(--brand-primary);
  border-color: var(--brand-primary);
}

.carousel-btn.prev { left: var(--space-lg); }
.carousel-btn.next { right: var(--space-lg); }

/* Newsletter */
.newsletter-section {
  background-color: var(--brand-primary);
  color: var(--text-primary);
  text-align: center;
}

.newsletter-section p {
  color: var(--text-primary);
  opacity: 0.9;
  margin: 0 auto var(--space-lg);
}

.newsletter-form {
  max-width: 500px;
  margin: 0 auto;
  display: flex;
  gap: var(--space-sm);
  position: relative;
}

.newsletter-form input {
  flex: 1;
  padding: 1rem 1.5rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 1.125rem;
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--text-primary);
}

.newsletter-msg {
  position: absolute;
  bottom: -30px;
  left: 0;
  width: 100%;
  font-size: 0.875rem;
  font-weight: 500;
}

.newsletter-msg.success { color: var(--bg-surface); }
.newsletter-msg.error { color: #ffcccc; }

/* CTA Block (Free Trial) */
.cta-block {
  text-align: center;
  background: linear-gradient(45deg, var(--bg-surface), var(--bg-elevated));
  border: 1px solid var(--brand-primary);
  border-radius: var(--radius-lg);
  padding: var(--space-xl) var(--space-md);
}

/* Footer */
.footer {
  background-color: #000;
  padding: var(--space-xl) 0 var(--space-md);
  margin-top: auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
  margin-bottom: var(--space-xl);
}

.footer-col h4 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
  color: var(--text-primary);
}

.footer-col ul li {
  margin-bottom: var(--space-sm);
}

.footer-col ul li a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-col ul li a:hover {
  color: var(--brand-primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  border-top: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.country-selector {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

/* Responsive */
@media (max-width: 992px) {
  .grid-2 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-links { display: none; }
  .mobile-menu-btn { display: block; }
}

@media (max-width: 768px) {
  .hero-actions { flex-direction: column; }
  .toggle-btn { padding: 1rem; font-size: 1rem; flex: 1; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .carousel-btn { width: 40px; height: 40px; font-size: 1.25rem; }
  .carousel-btn.prev { left: var(--space-sm); }
  .carousel-btn.next { right: var(--space-sm); }
  .footer-bottom { flex-direction: column; gap: var(--space-md); text-align: center; }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. Mobile Menu (optional placeholder)
  const mobileBtn = document.querySelector('.mobile-menu-btn');
  if (mobileBtn) {
    mobileBtn.addEventListener('click', () => {
      const navLinks = document.querySelector('.nav-links');
      if(navLinks.style.display === 'flex') {
        navLinks.style.display = 'none';
      } else {
        navLinks.style.display = 'flex';
        navLinks.style.flexDirection = 'column';
        navLinks.style.position = 'absolute';
        navLinks.style.top = '100%';
        navLinks.style.left = '0';
        navLinks.style.width = '100%';
        navLinks.style.backgroundColor = 'rgba(0,0,0,0.9)';
        navLinks.style.padding = '1rem';
      }
    });
  }

  // 2. Carousel Interaction (Home)
  const track = document.getElementById('carousel-track');
  if (track) {
    const slides = Array.from(track.children);
    const nextBtn = document.getElementById('carousel-next');
    const prevBtn = document.getElementById('carousel-prev');
    let currentIndex = 0;

    // Set initial track position
    function updateCarousel() {
      // Each slide is 80% width + some padding. We want active slide centered.
      // Easiest is to transform based on index and screen width.
      const slideWidth = slides[0].getBoundingClientRect().width;
      // move track left by slideWidth * index
      track.style.transform = `translateX(-${currentIndex * slideWidth}px)`;

      slides.forEach((slide, i) => {
        if(i === currentIndex) {
          slide.classList.add('active');
        } else {
          slide.classList.remove('active');
        }
      });
    }

    if(nextBtn && prevBtn) {
      nextBtn.addEventListener('click', () => {
        if (currentIndex < slides.length - 1) {
          currentIndex++;
          updateCarousel();
        }
      });

      prevBtn.addEventListener('click', () => {
        if (currentIndex > 0) {
          currentIndex--;
          updateCarousel();
        }
      });
    }

    // Basic swipe support
    let touchStartX = 0;
    let touchEndX = 0;

    track.addEventListener('touchstart', e => {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });

    track.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      if (touchStartX - touchEndX > 50 && currentIndex < slides.length - 1) {
        currentIndex++;
        updateCarousel();
      }
      if (touchEndX - touchStartX > 50 && currentIndex > 0) {
        currentIndex--;
        updateCarousel();
      }
    });

    // Initial call
    // Set timeout to ensure CSS is applied
    setTimeout(updateCarousel, 100);
    window.addEventListener('resize', updateCarousel);
  }

  // 3. Floor vs Treadmill Toggle (The Workout)
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const togglePanes = document.querySelectorAll('.toggle-content-pane');

  if (toggleBtns.length > 0) {
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const targetId = btn.getAttribute('data-target');

        // Update buttons
        toggleBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        // Update panes
        togglePanes.forEach(pane => {
          if(pane.id === targetId) {
            pane.classList.add('active');
          } else {
            pane.classList.remove('active');
          }
        });
      });
    });
  }

  // 4. Instructor Filtering
  const filterBtns = document.querySelectorAll('.filter-btn');
  const instructorCards = document.querySelectorAll('.instructor-card');

  if (filterBtns.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Update active class
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const filterValue = btn.getAttribute('data-filter');

        instructorCards.forEach(card => {
          if (filterValue === 'all' || card.getAttribute('data-location') === filterValue) {
            card.classList.remove('d-none');
          } else {
            card.classList.add('d-none');
          }
        });
      });
    });
  }

  // 5. FAQ Accordion
  const accordionItems = document.querySelectorAll('.accordion-item');
  if (accordionItems.length > 0) {
    accordionItems.forEach(item => {
      const header = item.querySelector('.accordion-header');
      header.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Close all
        accordionItems.forEach(acc => acc.classList.remove('active'));

        // Open clicked if it wasn't active
        if (!isActive) {
          item.classList.add('active');
        }
      });
    });
  }

  // 6. Newsletter Validation
  const newsletterForm = document.getElementById('newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = newsletterForm.querySelector('input[type="email"]');
      const msg = document.getElementById('newsletter-msg');
      const email = input.value.trim();

      const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;

      if (emailRegex.test(email)) {
        msg.textContent = 'Success! You are now subscribed.';
        msg.className = 'newsletter-msg success';
        input.value = '';
      } else {
        msg.textContent = 'Please enter a valid email address.';
        msg.className = 'newsletter-msg error';
      }
    });
  }

  // 7. Country Selector
  const countrySelect = document.getElementById('country-select-footer');
  if (countrySelect) {
    countrySelect.addEventListener('change', (e) => {
      console.log('Country changed to: ', e.target.value);
      // In a real app, this might redirect or reload with locale settings.
    });
  }
});
